// Cloudflare entry point: wraps the Next.js app built by OpenNext, adds the
// live-updates WebSocket and blocks cross-site writes before they reach the app.
// @ts-ignore: generated by `opennextjs-cloudflare build`
import { default as nextHandler } from '../.open-next/worker.js';

export { Hub } from './hub';

interface Env {
  DB: D1Database;
  HUB: DurableObjectNamespace;
}

const SESSION_COOKIES = ['__Host-pl_session', 'pl_session'];

function readCookie(req: Request, name: string): string | null {
  const raw = req.headers.get('Cookie') || '';
  for (const part of raw.split(';')) {
    const [k, ...v] = part.trim().split('=');
    if (k === name) return decodeURIComponent(v.join('='));
  }
  return null;
}

async function sha256(text: string): Promise<string> {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

function sameOrigin(req: Request, url: URL): boolean {
  const origin = req.headers.get('Origin');
  if (origin) {
    try {
      return new URL(origin).host === url.host;
    } catch {
      return false;
    }
  }
  const site = req.headers.get('Sec-Fetch-Site');
  return !site || site === 'same-origin' || site === 'none';
}

async function liveSocket(req: Request, env: Env, url: URL): Promise<Response> {
  if (req.headers.get('Upgrade') !== 'websocket') return new Response('Expected WebSocket', { status: 426 });
  if (!sameOrigin(req, url)) return new Response('Forbidden', { status: 403 });

  const token = SESSION_COOKIES.map((n) => readCookie(req, n)).find(Boolean);
  if (!token) return new Response('Not signed in', { status: 401 });
  const row = await env.DB.prepare(
    'SELECT s."userId", s."expiresAt", u."isBanned" FROM "AuthSession" s JOIN "User" u ON u."id" = s."userId" WHERE s."tokenHash" = ?',
  )
    .bind(await sha256(token))
    .first<{ userId: string; expiresAt: number | string; isBanned: number }>();
  if (!row || row.isBanned || new Date(row.expiresAt).getTime() < Date.now()) return new Response('Not signed in', { status: 401 });

  const hub = env.HUB.get(env.HUB.idFromName('global'));
  const headers = new Headers(req.headers);
  headers.set('x-user-id', row.userId);
  return hub.fetch(new Request('https://hub/connect', { headers }));
}

export default {
  async fetch(req: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(req.url);
    if (url.pathname === '/api/live') return liveSocket(req, env, url);

    // CSRF: any request that changes data must come from our own pages.
    if (url.pathname.startsWith('/api/') && !['GET', 'HEAD', 'OPTIONS'].includes(req.method) && !sameOrigin(req, url)) {
      return Response.json({ error: 'Cross-site request blocked' }, { status: 403 });
    }
    return nextHandler.fetch(req, env, ctx);
  },
} satisfies ExportedHandler<Env>;
